        @lru_cache(None)
        def dp(mask):
            for em in edge_masks:
                if (mask & em) == em:
                    if not dp(mask ^ em):
                        return True
            return False
        return dp(full)

    def edges_for(rule):
        es=[]
        for i in range(n):
            for j in range(i+1,n):
                if rule(cards[i], cards[j]):
                    es.append((i,j))
        return es

    # define rules
    def rule_or(a,b): return a[0]==b[0] or a[1]==b[1]
    def rule_xor(a,b): return (a[0]==b[0]) ^ (a[1]==b[1])
    def rule_and(a,b): return a[0]==b[0] and a[1]==b[1]
    def rule_cross(a,b): return a[0]==b[1] or a[1]==b[0]
    def rule_any(a,b): return a[0]==b[0] or a[1]==b[1] or a[0]==b[1] or a[1]==b[0]
    def rule_front_only(a,b): return a[0]==b[0]
    def rule_back_only(a,b): return a[1]==b[1]

    rules = {
        "or": rule_or,
        "xor": rule_xor,
        "and": rule_and,
        "cross": rule_cross,
        "any": rule_any,
        "front": rule_front_only,
        "back": rule_back_only,
    }

    details=""
    for name,rule in rules.items():
        es=edges_for(rule)
        em=tuple((1<<i)|(1<<j) for i,j in es)
        full=(1<<n)-1
        # need fresh cache per rule
        @lru_cache(None)
        def dp(mask):
            for e in em:
