        (7, [(51381329, 616885263), (993367575, 914515460), (654229289, 974168752), (899846144, 602506004), (573578923, 408717435), (344212430, 581675303), (485223917, 933528365)], "Aoki"),
        (3, [(859120875, 859120875), (859120875, 859120875), (859120875, 859120875)], "Takahashi"),
        (8, [(252672450, 252672450), (109279706, 252672450), (11860455, 820449974), (11860455, 820449974), (820449974, 745822502), (109279706, 745822502), (252672450, 252672450), (252672450, 109279706)], "Takahashi"),
    ]

    for idx,(tn,tcards,exp) in enumerate(test_cases):
        details+=f"\nCase {idx} n={tn} exp={exp}:\n"
